 const cleanSections=Array.from(clean.children).slice(1),up=cleanSections.find(el=>el.dataset.group==='Upstacking')||section('Upstacking'),accommodation=cleanSections.find(el=>el.dataset.group==='Accommodation stacking')||section('Accommodation stacking');rename(accommodation,'Accommodation Stacking');clean.replaceChildren(clean.children[0],up,accommodation);
