function revealGroup(name){
 function visit(node,ancestors){if(node.dataset?.group===name){for(const el of [...ancestors,node])if(el.tagName==='DETAILS')el.open=true;return true;}for(const child of Array.from(node.children||[]))if(visit(child,[...ancestors,node]))return true;return false;}
 return visit($('situationList'),[]);
}

function navigation(categories){const parent=categories.get('Introduction');for(const lesson of intros){if(lesson.chapter)continue;const b=document.createElement('button');b.className='course-lesson-link';b.textContent=lesson.title;b.onclick=()=>{parent.open=true;openIntro(lesson.id);bridge?.closeMenu();};parent.append(b);}}
function init(b){bridge=b;root.TetrisCourseSearch?.init();try{const id=new URL(location.href).searchParams.get('lesson');if(intros.some(l=>l.id===id)){if(new URL(location.href).searchParams.get('practice')!=='notation')openIntro(id);revealGroup(intros.find(l=>l.id===id).group||intros.find(l=>l.id===id).chapter||'Introduction');}}catch{}}
function openSituation(key){bridge?.selectSituation?.(key);bridge?.closeMenu();}
